arguments.command:
cd /testbed && python3 << 'EOF'
from rest_framework.routers import SimpleRouter

router = SimpleRouter()
print("SimpleRouter attributes:")
for attr in dir(router):
    if not attr.startswith('_'):
        val = getattr(router, attr)
        if not callable(val):
            print(f"  {attr}: {val}")
EOF

